// src/shared/aggregate.helpers.ts
var AggregateHelper = class {
  empty() {
    return {
      llmCalls: 0,
      llmErrors: 0,
      toolCalls: 0,
      toolErrors: 0,
      skillCalls: 0,
      skillErrors: 0,
      tokens: { input: 0, output: 0, reasoning: 0, cacheRead: 0 },
      cost: 0,
      workDurationMs: 0
    };
  }
  emptyToolStats() {
    return { calls: 0, errors: 0, durationMs: 0 };
  }
  emptySkillStats() {
    return { calls: 0, errors: 0, avgDurationMs: 0 };
  }
  emptySession() {
    return { ...this.empty(), sessionErrors: 0 };
  }
  getOrCreate(map, key, factory) {
    let value = map.get(key);
    if (!value) {
      value = factory();
      map.set(key, value);
    }
    return value;
  }
  addTokens(target, source) {
    target.input += source.input;
    target.output += source.output;
    target.reasoning += source.reasoning;
    target.cacheRead += source.cacheRead;
  }
  addToAggregate(target, source) {
