  lines.push(`| Output Tokens | ${fmt(t.tokens.output)} |`);
  lines.push(`| Reasoning Tokens | ${fmt(t.tokens.reasoning)} |`);
  lines.push(`| Cache Read Tokens | ${fmt(t.tokens.cacheRead)} |`);
