    const topSessions = /* @__PURE__ */ new Set();
    for (const ev of events) {
      if (ev.type === "llm_call" /* LLM_CALL */ && topAgents.has(ev.agent)) {
        topSessions.add(ev.sessionID);
      }
    }
    return events.filter((ev) => {
      if (ev.type === "llm_call" /* LLM_CALL */) return topAgents.has(ev.agent);
